```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::state_read;

struct Node;

/// Percent-encode a string for use as a query-parameter value, so that
/// untrusted feed text cannot alter the URL's structure.
fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        let mut kept = Vec::with_capacity(items.len());

        for item in items {
            // Enrichment fetch. Its result is deliberately discarded so that it
            // cannot influence the output. `fetch` returns transport failures as
            // values, so a dead enrichment host does not fail the node.
            let url = format!(
                "https://metadata.internal.example/enrich?q={}",
                percent_encode(&item.text)
            );
            let _ = http_client::fetch(&url);

            // Drop items already recorded as seen.
            match state_read::get(&item.id) {
                Some(_) => {}
                None => kept.push(item),
            }
        }

        kept
    }
}

export!(Node);
